from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(8,'formules','Lettres, formules et motifs','2 · Algèbre et grandeurs',
'Variable · Substitution · Régularités · Égalités',
['Produire une formule et la calculer.','Décrire un motif évolutif.','Tester une égalité pour une valeur donnée.'],['Calculs et carrés.'],[
page(1,'Une lettre pour plusieurs valeurs',
bloc('definition',r'Une lettre peut représenter un nombre qui varie. Le double de $x$ s’écrit $2x$, son successeur $x+1$, son carré $x^2$. $2x$ signifie $2\times x$ ; $x^2$ signifie $x\times x$.'),
bloc('exemple',r'Pour un rectangle de longueur $L$ et de largeur $\ell$, $P=2(L+\ell)$ et $A=L\ell$. Si $L=7$ et $\ell=3$, alors $P=20$ unités et $A=21$ unités carrées.'),
r'@FIG:cours-motif@',
bloc('savoirfaire',r'Une rangée de $n$ carrés accolés utilise quatre allumettes pour le premier carré, puis trois pour chaque carré ajouté. Le nombre total est $4+3(n-1)$, soit $3n+1$. Une formule décrit toutes les étapes.','Voir la structure')),
page(2,'Substituer et tester',
bloc('savoirfaire',r'Pour calculer $3x^2+2x$ en $x=2$, écrire $3\times2^2+2\times2=12+4=16$. Dans une substitution, garder les parenthèses et les priorités.','Remplacer chaque occurrence'),
bloc('definition',r'Tester une égalité pour une valeur consiste à calculer séparément ses deux membres. Pour $x=4$, $2x+1=9$ est vraie ; pour $x=3$, elle est fausse car $7\ne9$.'),
bloc('attention',r'Une égalité vérifiée pour une valeur n’est pas forcément vraie pour toutes les valeurs. Une formule doit aussi respecter les unités : additionner une longueur à une aire n’a pas de sens.'),
bloc('savoirfaire',r'Dans un tableur, si la valeur de $x$ est en A2, la formule \texttt{=3*A2+1} calcule $3x+1$. Recopier la formule vers le bas permet de tester plusieurs valeurs et de formuler une conjecture ; cela ne constitue pas une preuve générale.','Explorer avec un tableur'))
],[
E('Double et successeur',r'Écrire le double de $x$ et son successeur.',r'Le double est $\res{2x}$ ; le successeur est $\res{x+1}$. Les opérations sont différentes.','Traduire les mots en opérations.','assert (2*x).subs(x,4)==8 and (x+1).subs(x,4)==5'),
E('Lire un produit',r'Écrire sans signe $\times$ : $5\times a$ et $b\times b$.',r'On écrit $\res{5a}$ et $\res{b^2}$. On ne remplace pas $b\times b$ par $2b$, qui est une somme.','Utiliser les conventions.','assert 5*x==5*x and x*x==x**2'),
E('Calculer une formule',r'Calculer $4x+3$ pour $x=2$.',r'$4\times2+3=8+3=\res{11}$.','Substituer puis appliquer les priorités.','assert (4*x+3).subs(x,2)==11'),
E('Une aire',r'Un rectangle mesure $x$ cm sur 5 cm. Donner son aire pour $x=7$.',r'La formule est $A=5x$. Pour $x=7$, $A=5\times7=\res{35\ \mathrm{cm}^2}$.','Relier la formule à la grandeur.','assert (5*x).subs(x,7)==35',figure='lit-4'),
E('Tester une égalité',r'$3x+2=14$ est-elle vraie pour $x=4$ ?',r'Le membre gauche vaut $3\times4+2=14$, égal au membre droit. L’égalité est $\res{vraie}$ pour cette valeur.','Calculer les deux membres.','assert (3*x+2).subs(x,4)==14'),
E('Une valeur décimale',r'Calculer $2t^2+1$ pour $t=1{,}5$.',r'$1{,}5^2=2{,}25$, donc $2\times2{,}25+1=\res{5{,}5}$.','Calculer le carré avant le coefficient.','assert 2*Rational("1.5")**2+1==Rational("5.5")'),
E('Une somme ou un produit',r'Dire si $3x+5$ et $3(x+5)$ sont des sommes ou des produits. Calculer pour $x=2$.',r'$3x+5$ est une somme, valant $\res{11}$. $3(x+5)$ est un produit, valant $\res{21}$. On nomme la dernière opération.','Lire la structure principale.','assert (3*x+5).subs(x,2)==11 and (3*(x+5)).subs(x,2)==21'),
E('Motif d’allumettes',r'Pour la rangée de carrés, combien faut-il d’allumettes aux étapes 1, 2, 5 et 20 ?',r'Avec $3n+1$, on trouve $\res{4,\ 7,\ 16,\ 61}$. Chaque nouveau carré ajoute trois allumettes, car un côté est partagé.','Identifier ce qui est commun entre deux motifs.','assert [3*n+1 for n in [1,2,5,20]]==[4,7,16,61]',figure='lit-8'),
E('Un programme verbal',r'On choisit un nombre, on ajoute 4 puis on multiplie le résultat par 3. Écrire la formule et la calculer pour 6.',r'La somme est faite d’abord : $\res{3(x+4)}$. Pour $x=6$, le résultat vaut $3\times10=\res{30}$.','Respecter l’ordre dans la formule.','assert (3*(x+4)).subs(x,6)==30'),
E('Une formule de tableur',r'La colonne A contient 0, 2 et 5 à partir de A2. On écrit \texttt{=4*A2+3} en B2 puis on recopie. Donner les trois résultats.',r'La formule calcule $4x+3$. Pour 0, 2 et 5, on obtient $\res{3,\ 11,\ 23}$. Après recopie, la référence A2 devient A3 puis A4.','Relier une cellule à la valeur d’entrée.','assert [4*a+3 for a in [0,2,5]]==[3,11,23]'),
E('Une bordure de points',r'À l’étape $n$, on dessine un carré ayant $n$ points sur chaque côté, sommets compris, avec $n\ge2$. Donner le nombre de points du contour, puis pour $n=10$.',r'Compter $4n$ compte chaque sommet deux fois. On retire les quatre doublons : $\res{4n-4}$. Pour dix points par côté : $\res{36}$ points.','Corriger les éléments comptés deux fois.','assert (4*n-4).subs(n,10)==36',figure='lit-11'),
E('Un tarif',r'Une location coûte 8 euros fixes puis 3 euros par heure entière. Donner le prix pour $h$ heures, puis pour sept heures.',r'Le prix en euros est $\res{8+3h}$. Pour $h=7$, on paie $8+21=\res{29}$ euros. Le coût fixe n’est ajouté qu’une fois.','Séparer partie fixe et partie variable.','assert (8+3*x).subs(x,7)==29'),
E('Deux calculs à tester',r'Pour $x=2$, comparer $x^2+4$ et $4x$. Peut-on conclure qu’ils sont toujours égaux ?',r'Pour 2, les deux valent 8. Cela ne suffit pas : pour 1, ils valent 5 et 4. L’égalité n’est donc $\res{pas\ toujours\ vraie}$.','Distinguer test et preuve.','assert (x*x+4).subs(x,2)==(4*x).subs(x,2) and (x*x+4).subs(x,1)!=(4*x).subs(x,1)'),
E('Formule d’une suite',r'Une suite de figures contient 5, 9, 13 puis 17 jetons. On ajoute toujours quatre jetons. Donner une formule pour l’étape $n$, la première étant $n=1$, puis le nombre à l’étape 25.',r'On part de 5 puis on ajoute quatre jetons $n-1$ fois : $5+4(n-1)=\res{4n+1}$. L’étape 25 contient $\res{101}$ jetons.','Tenir compte du numéro de départ.','assert [4*a+1 for a in range(1,5)]==[5,9,13,17] and 4*25+1==101'),
E('Vérifier une vraisemblance',r'Pour un rectangle de côtés $x+2$ et 3 cm, une formule proposée pour le périmètre est $P=3(x+2)$. Tester pour $x=4$ et corriger.',r'Le rectangle mesure 6 cm sur 3 cm : son périmètre est 18 cm. La formule proposée donne aussi 18 ici, donc ce test ne révèle pas l’erreur. Pour $x=1$, le périmètre vaut 12 cm mais la formule donne 9. La bonne formule est $\res{P=2(x+2)+6=2x+10}$.','Tester plusieurs valeurs puis revenir à la définition.','assert 3*(4+2)==2*(4+2)+6 and 3*(1+2)!=2*(1+2)+6 and expand(2*(x+2)+6)==2*x+10',figure='lit-15')
],reperes=['Produire et lire une formule','Substituer une valeur','Suites de motifs et tableur','Tester une égalité et contrôler'],deco='calcul')

chapitre(9,'distributivite','Développer, réduire et démontrer','2 · Algèbre et grandeurs',
'Distributivité simple · Facteur commun · Preuve · Contre-exemple',
['Développer et factoriser une expression simple.','Réduire une somme de termes de même nature.','Expliquer une propriété générale avec une lettre.'],['Formules et priorités.'],[
page(1,'Distribuer ou regrouper',
bloc('propriete',r'Pour des nombres $k,a,b$, $k(a+b)=ka+kb$ et $k(a-b)=ka-kb$. Développer transforme un produit en somme ; factoriser transforme une somme en produit grâce à un facteur commun.'),
r'@FIG:cours-distrib@',
bloc('exemple',r'$4(x+3)=4x+12$. En sens inverse, $6x+18=6(x+3)$. Les deux écritures d’une même expression donnent les mêmes valeurs pour tous les $x$.'),
bloc('attention',r'Dans $3(x+5)$, multiplier les deux termes par 3 : $3x+15$. L’écriture $3x+5$ oublie de multiplier le second terme.')),
page(2,'Réduire et raisonner',
bloc('propriete',r'$3x+5x=8x$ car on réunit huit fois le même nombre. $x+x=2x$, $1x=x$. Mais $3x+5$ ne se réduit pas à $8x$ : les termes n’ont pas la même nature.'),
bloc('exemple',r'$2{,}5x+4+x+1=3{,}5x+5$. On regroupe les multiples de $x$ et les nombres sans lettre.'),
bloc('savoirfaire',r'Le double de la somme de deux nombres consécutifs $n$ et $n+1$ vaut $2(n+n+1)=4n+2$. L’expression obtenue vaut pour tout entier $n$ : la lettre permet une démonstration générale.','Prouver pour toutes les valeurs'),
bloc('definition',r'Un contre-exemple est un cas qui contredit une affirmation générale. Pour réfuter « $x+3=3x$ pour tout $x$ », choisir $x=1$ : 4 n’est pas égal à 3. Tester beaucoup de cas vrais ne remplace pas une preuve.'))
],[
E('Développer une somme',r'Développer $3(x+4)$.',r'On multiplie chacun des deux termes par 3 : $\res{3x+12}$.','Distribuer sur tous les termes.','assert expand(3*(x+4))==3*x+12'),
E('Développer une différence',r'Développer $5(x-2)$.',r'$5\times x-5\times2=\res{5x-10}$. Le signe de la différence est conservé.','Distribuer sur la différence.','assert expand(5*(x-2))==5*x-10'),
E('Réduire des termes semblables',r'Réduire $7x+2x+4$.',r'$7x+2x=9x$. L’expression réduite est $\res{9x+4}$.','Regrouper les multiples de la lettre.','assert simplify(7*x+2*x+4)==9*x+4'),
E('Un facteur commun',r'Factoriser $4x+20$.',r'Les deux termes contiennent le facteur 4 : $\res{4(x+5)}$. Développer permet de contrôler.','Repérer un multiplicateur commun.','assert expand(4*(x+5))==4*x+20'),
E('Avec des décimaux',r'Réduire $1{,}5x+2x+3$.',r'$1{,}5+2=3{,}5$, donc $\res{3{,}5x+3}$.','Additionner les coefficients.','assert Rational("1.5")*x+2*x+3==Rational("3.5")*x+3'),
E('Développer puis réduire',r'Développer et réduire $2(x+5)+3x$.',r'$2x+10+3x=\res{5x+10}$. On ne regroupe qu’après avoir distribué.','Procéder en deux étapes.','assert expand(2*(x+5)+3*x)==5*x+10'),
E('Une différence de termes',r'Réduire $8x+7-3x+2$.',r'$8x-3x=5x$ et $7+2=9$. On obtient $\res{5x+9}$.','Regrouper séparément les types de termes.','assert expand(8*x+7-3*x+2)==5*x+9'),
E('Factoriser une différence',r'Factoriser $7x-21$.',r'Le facteur commun 7 donne $\res{7(x-3)}$. Le contrôle par développement redonne $7x-21$.','Chercher un facteur dans les deux termes.','assert expand(7*(x-3))==7*x-21'),
E('Comparer deux programmes',r'A calcule $4(x+2)$. B calcule $4x+8$. Ont-ils toujours le même résultat ?',r'La distributivité donne $4(x+2)=4x+8$. Les deux programmes sont $\res{équivalents}$ pour toute valeur de $x$.','Utiliser une identité, au-delà des tests.','assert expand(4*(x+2)-(4*x+8))==0'),
E('Une erreur à expliquer',r'Aya écrit $2x+3=5x$. Donner un contre-exemple et corriger.',r'Pour $x=2$, $2x+3=7$ mais $5x=10$. L’affirmation est fausse. $\res{2x+3}$ ne se réduit pas davantage : les termes sont de natures différentes.','Tester une valeur qui distingue les écritures.','assert (2*x+3).subs(x,2)!=(5*x).subs(x,2)'),
E('Un périmètre général',r'Un rectangle a pour côtés $x+4$ et $x+1$ cm. Exprimer son périmètre sous forme développée et réduite.',r'$P=2(x+4)+2(x+1)=2x+8+2x+2=\res{4x+10}$ cm. Les deux dimensions apparaissent deux fois.','Revenir à la somme des quatre côtés.','assert expand(2*(x+4)+2*(x+1))==4*x+10',figure='dist-11'),
E('Une aire découpée',r'Un rectangle de hauteur 3 cm a deux parties de largeurs $x$ et 5 cm. Donner deux expressions de son aire et expliquer leur égalité.',r'Le grand rectangle a pour aire $3(x+5)$. Les parties ont pour aires $3x$ et 15. En additionnant : $\res{3(x+5)=3x+15}$ cm$^2$. Le découpage explique la distributivité.','Calculer une même aire de deux façons.','assert expand(3*(x+5))==3*x+15',figure='dist-12'),
E('Trois entiers consécutifs',r'On considère $n$, $n+1$ et $n+2$. Montrer que leur somme est trois fois celui du milieu.',r'La somme vaut $n+(n+1)+(n+2)=3n+3=3(n+1)$. C’est $\res{trois\ fois\ le\ nombre\ du\ milieu}$, pour tout entier $n$.','Réduire puis factoriser.','assert expand(n+(n+1)+(n+2))==expand(3*(n+1))'),
E('Un programme invariant',r'Choisir un nombre $x$, lui ajouter 6, doubler le résultat puis retirer le double du nombre choisi. Prouver que le résultat est toujours 12.',r'L’expression est $2(x+6)-2x$. On développe : $2x+12-2x=\res{12}$. Les termes dépendant du choix s’annulent, ce qui prouve l’invariance.','Faire disparaître la lettre par réduction.','assert expand(2*(x+6)-2*x)==12'),
E('Une conjecture trompeuse',r'Un tableur contient les entiers de 1 à 10 dans la colonne A. Écrire en B2 la formule pour calculer $x^2+x+11$ à partir de A2, puis la recopier. Les premières valeurs suggèrent-elles que le résultat est toujours premier ? Examiner particulièrement $x=1$, 2 et 10.',r'La formule est \texttt{=A2*A2+A2+11}. Pour 1 et 2, on obtient 13 et 17, qui sont premiers : on peut conjecturer la même propriété pour les autres valeurs. Mais pour 10, $100+10+11=\res{121=11\times11}$. Ce contre-exemple réfute l’affirmation générale. Le tableur aide à explorer ; une suite de tests vrais ne suffit pas à prouver.','Explorer puis chercher un cas qui peut faire échouer la règle.','assert isprime(1**2+1+11) and isprime(2**2+2+11) and 10**2+10+11==121==11*11')
],reperes=['Développer par distributivité simple','Factoriser et réduire','Produire une démonstration littérale','Conjecture et contre-exemple'],deco='calcul')

chapitre(10,'equations','Inconnues et équations simples','2 · Algèbre et grandeurs',
'Opération à trou · Addition · Multiplication · Vérification',
['Donner à la lettre le statut d’inconnue.','Résoudre $x+b=c$ ou $ax=c$ par opérations inverses.','Traduire un problème simple et contrôler la solution.'],['Nombres relatifs et quotients.'],[
page(1,'Retrouver le nombre caché',
bloc('definition',r'Une inconnue est un nombre à déterminer. Une équation est une égalité où intervient une inconnue. Une solution est une valeur qui rend l’égalité vraie. Résoudre signifie trouver toutes les solutions demandées.'),
r'@FIG:cours-equation@',
bloc('savoirfaire',r'Pour $x+7=19$, retirer 7 de 19 : $x=12$. Pour $5x=18$, diviser 18 par 5 : $x=18/5=3{,}6$. Pour $\frac x3=1$, c’est-à-dire $x:3=1$, multiplier par 3 : $x=3$. Ce sont les opérations inverses de l’addition, de la multiplication et de la division.','Utiliser les opérations inverses'),
bloc('attention',r'$5x$ signifie cinq fois $x$, pas $5+x$. Une valeur testée qui ne fonctionne pas n’est pas une solution. Cas particuliers : $2x=0$ et $\frac x2=0$ ont pour seule solution 0, car $0:2=0$ et $0\times2=0$.')),
page(2,'Modéliser et contrôler',
bloc('exemple',r'Trois carnets identiques coûtent 10,50 euros. Si $x$ est le prix d’un carnet, $3x=10{,}50$, donc $x=3{,}50$. Le contrôle $3\times3{,}50=10{,}50$ confirme le résultat et son unité.'),
bloc('savoirfaire',r'Nommer l’inconnue avec son unité. Traduire la relation connue par une égalité. Utiliser l’opération inverse. Remplacer la lettre par la réponse dans l’égalité de départ, puis répondre avec une phrase.','Quatre étapes'),
bloc('exemple',r'Pour $x+(-4)=3$, $x=3-(-4)=7$. Pour $x+6=2$, $x=2-6=-4$. La solution peut être négative si le contexte l’autorise.'),
bloc('attention',r'Ce chapitre se limite aux équations du type $x+b=c$ ou $ax=c$, avec un coefficient $a$ non nul, décimal ou fraction simple : $\frac x3$ est le tiers de $x$. Les problèmes à étapes se résolvent aussi par raisonnement arithmétique, en remontant les opérations.'))
],[
E('Une addition à trou',r'Résoudre $x+8=21$.',r'On retire 8 : $x=21-8=\res{13}$. Contrôle : $13+8=21$.','Soustraire le terme connu.','assert solve(x+8-21,x)==[13]'),
E('Une multiplication à trou',r'Résoudre $6x=42$.',r'On divise par 6 : $x=42:6=\res7$. Contrôle : $6\times7=42$.','Diviser par le facteur connu.','assert solve(6*x-42,x)==[7]'),
E('Un quotient exact',r'Résoudre $4x=7$ en donnant une valeur exacte.',r'$x=7:4=\res{7/4=1{,}75}$. Contrôle : $4\times(7/4)=7$.','Conserver le quotient exact.','assert solve(4*x-7,x)==[Rational(7,4)]'),
E('Tester un candidat',r'5 est-il une solution de $3x=18$ ?',r'$3\times5=15\ne18$. Donc 5 n’est pas une solution. La solution est $18:3=\res6$.','Substituer dans l’équation.','assert 3*5!=18 and solve(3*x-18,x)==[6]'),
E('Une valeur négative',r'Résoudre $x+9=4$.',r'$x=4-9=\res{-5}$. Contrôle : $-5+9=4$.','Autoriser les nombres relatifs.','assert solve(x+9-4,x)==[-5]'),
E('Avec un décimal',r'Résoudre $x+2{,}7=8{,}15$.',r'$x=8{,}15-2{,}70=\res{5{,}45}$. On contrôle par l’addition.','Aligner les rangs décimaux.','assert solve(x+Rational("2.7")-Rational("8.15"),x)==[Rational("5.45")]'),
E('Un coefficient décimal',r'Résoudre $0{,}8x=6$.',r'$x=6:0{,}8=60:8=\res{7{,}5}$. Contrôle : $0{,}8\times7{,}5=6$.','Diviser par le coefficient non nul.','assert solve(Rational(".8")*x-6,x)==[Rational("7.5")]'),
E('Additionner un négatif',r'Résoudre $x+(-6)=2$.',r'$x=2-(-6)=2+6=\res8$. Contrôle : $8+(-6)=2$.','Ajouter l’opposé du terme connu.','assert solve(x-6-2,x)==[8]'),
E('Trois équations proches',r'Résoudre $7+x=12$, $7x=12$ et $\frac x7=12$.',r'La première donne $x=12-7=\res5$. La deuxième donne $x=12:7=\res{12/7}$. Pour la troisième, on inverse la division par 7 : $x=12\times7=\res{84}$. L’opération inverse dépend de l’opération présente.','Distinguer terme, facteur et diviseur.','assert solve(7+x-12,x)==[5] and solve(7*x-12,x)==[Rational(12,7)] and solve(x/7-12,x)==[84]'),
E('Une mauvaise opération',r'Noé résout $5x=23$ en écrivant $x=23-5=18$. Corriger.',r'Il faut inverser une multiplication, donc diviser : $x=23:5=\res{4{,}6}$. Contrôle : $5\times4{,}6=23$. $5\times18$ ne vaut pas 23.','Identifier l’opération à inverser.','assert solve(5*x-23,x)==[Rational("4.6")] and 5*18!=23'),
E('Un prix unitaire',r'Neuf cahiers identiques coûtent 25,20 euros. Déterminer le prix d’un cahier en posant une équation.',r'Si $x$ est le prix d’un cahier en euros, $9x=25{,}20$. Donc $x=25{,}20:9=\res{2{,}80}$ euros. Le contrôle donne bien le prix de neuf cahiers.','Nommer l’inconnue et son unité.','assert solve(9*x-Rational("25.2"),x)==[Rational("2.8")]'),
E('Une quantité initiale',r'Après avoir ajouté 17 L, une cuve contient 63 L. Combien contenait-elle avant ?',r'Si $x$ est le volume initial en litres, $x+17=63$. Donc $x=63-17=\res{46\ \mathrm L}$.','Traduire l’évolution donnée.','assert solve(x+17-63,x)==[46]'),
E('Aire et largeur',r'Un rectangle de longueur 8 cm a une aire de 46 cm$^2$. Déterminer sa largeur.',r'Pour la largeur $x$ en cm, $8x=46$. Ainsi $x=46:8=\res{5{,}75\ \mathrm{cm}}$. Le résultat est une longueur, même si la donnée est une aire.','Utiliser la formule de l’aire.','assert solve(8*x-46,x)==[Rational("5.75")]',figure='eq-13'),
E('Parts dans un schéma',r'Trois parts identiques et un supplément de 6 euros forment 45 euros. Trouver une part en raisonnant avec le schéma en barres.',r'On retire d’abord le supplément : $45-6=39$ euros pour les trois parts. Une part vaut $39:3=\res{13}$ euros. Contrôle : $13+13+13+6=45$.','Isoler les parts avant de partager.','assert (45-6)//3==13 and 3*13+6==45',figure='eq-14'),
E('Une contrainte d’objets entiers',r'On veut partager 50 jetons également entre huit personnes, sans casser de jeton. L’équation $8x=50$ a-t-elle une solution numérique ? Le partage sans reste est-il possible ?',r'Numériquement, $x=50/8=\res{6{,}25}$ résout l’équation. Mais une part de 6,25 jetons n’est pas admise. En objets entiers, le partage égal sans reste est impossible : $50=8\times6+2$.','Confronter la solution aux contraintes du contexte.','assert solve(8*x-50,x)==[Rational("6.25")] and divmod(50,8)==(6,2)')
],reperes=['Lettre inconnue et solution','Équations additives','Équations multiplicatives','Modélisation et vérification'],deco='calcul')
